// EXECUTION-LESSONS 2.25: the frozen block is GENERATED from the tasks' own FILES arrays. Two
// hand-maintained lists of the same fact drift by construction, and the last time one was
// hand-written it forbade the very files its task existed to create.
// ---------------------------------------------------------------------------------------------
function frozenBlock(tasks, self) {
  let s = "FROZEN PATHS WHILE THIS PIPELINE RUNS. A commit touching a path not listed for YOUR task\nfails the task.\n\n**THE RULE IS ONE SENTENCE: the plan's File Structure block is the complete set of files this\npipeline may touch, and each task may touch only its own rows.** Everything else in the repository\n- every other kernel file, every other module, every other test, `packages/contracts/**`,\n`.github/workflows/**`, `jest.config.cjs`, `tsconfig*`, `.env.example`, `pnpm-lock.yaml` - is\nfrozen to this pipeline.\n\nThis block was GENERATED from the tasks' own Files lists at compile time (EXECUTION-LESSONS 2.25),\nnot hand-written beside them, so it CANNOT contradict them. If it seems to, that is a finding.\n\n";
  s += "YOUR TASK (" + self.id.toUpperCase() + ") MAY TOUCH EXACTLY THESE, AND NOTHING ELSE:\n";
  self.files.forEach(function (f) { s += "    " + f + "\n" });
  s += "\nOWNED BY OTHER TASKS IN THIS PIPELINE - DO NOT TOUCH THEM, EVEN IF YOUR CHANGE WOULD BE CORRECT.\nIf you believe you cannot finish without one of these, that is a CHAIN HALT and a plan defect\nreport, never a quiet edit:\n";
  tasks.forEach(function (t) {
    if (t.id === self.id) return;
    s += "  " + t.id.toUpperCase() + ": " + t.files.join(", ") + "\n";
  });
  s += "\nNOTE ON SHARED FILES. Three files are touched by two tasks each and that is why this pipeline is\nstrictly sequential with one task per wave: `apps/core/src/kernel/config.ts` (T1 adds\nWORKER_STALE_AFTER_MS, T2 adds the four interval keys) and, across waves, nothing else overlaps.\nYou will find the other task's edit already in the file. Leave it exactly as it is.\n\nNOTE ON MUTANT SCRATCH (EXECUTION-LESSONS 2.14). Frozen-path rules govern what may be COMMITTED.\nTransient mutant scratch that is never committed and is deleted before your final counts may sit\nbeside its source even in a frozen directory - prefer a non-frozen location when one exists. The\ninvariant a reviewer actually checks is `git status --porcelain` empty, no `*.mutant.*` residue,\nand no frozen path in the diff.";
  return s;
}

